package com.abhishek.hotelbooking.controller; import com.abhishek.hotelbooking.dto.booking.*; import com.abhishek.hotelbooking.service.impl.BookingService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/bookings") public class BookingController { private final BookingService service; public BookingController(BookingService service){this.service=service;} @PostMapping public BookingResponse create(@Valid @RequestBody BookingRequest r,@org.springframework.security.core.annotation.AuthenticationPrincipal(expression="username") String email){return service.create(email,r);} @GetMapping("/me") public List<BookingResponse> mine(@org.springframework.security.core.annotation.AuthenticationPrincipal(expression="username") String email){return service.mine(email);} @PutMapping("/{id}/cancel") public BookingResponse cancel(@PathVariable Long id,@org.springframework.security.core.annotation.AuthenticationPrincipal(expression="username") String email){return service.cancel(email,id);} }